from PIL import Image
im=Image.open('sheet.png').convert('RGBA');w,h=im.size;pix=im.getchannel('A').tobytes()
for threshold in [16,32,64,128]:
 seen=bytearray(w*h);out=[]
 for idx,v in enumerate(pix):
  if v<threshold or seen[idx]:continue
  seen[idx]=1;q=[idx];ct=0;x0=w;y0=h;x1=y1=0
  while q:
   k=q.pop();ct+=1;x=k%w;y=k//w;x0=min(x,x0);y0=min(y,y0);x1=max(x,x1);y1=max(y,y1)
   for ny in range(max(0,y-1),min(h,y+2)):
    for nx in range(max(0,x-1),min(w,x+2)):
     n=ny*w+nx
     if pix[n]>=threshold and not seen[n]:seen[n]=1;q.append(n)
  if ct>1000:out.append((x0,y0,x1+1,y1+1,ct))
 print(threshold,len(out),sorted(out,key=lambda b:(b[1]//240,b[0])))
